SELECT CASE WHEN amount >= 1750 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, DATE_TRUNC('WEEK', paid_at) AS week_start, SIZE(COLLECT_SET(method)) AS num_methods, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN method = 'paypal' THEN 1 END), 0), 2) AS amount_per_paypal, MAX(amount) FILTER (WHERE method = 'cash') AS cash_max_amount FROM payments GROUP BY CASE WHEN amount >= 1750 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', paid_at) ORDER BY week_start DESC NULLS FIRST;
